import json,csv,re
tr=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
rows=list(csv.DictReader(open('data/scores.csv')))
byid={t['rating_id']:t for t in tr}
print(len(tr),len(rows),len(byid))
from collections import Counter
print(Counter(t['judge_model'] for t in tr))
print(Counter(tuple(sorted(t.keys())) for t in tr))
mism=0;issues=[]
for r in rows:
    t=byid.get(r['rating_id'])
    if t is None: issues.append(('missing',r['rating_id'])); continue
    fs=re.findall(r'FINAL SCORE:\s*(\S+)',t['judge_output'])
    da=re.findall(r'Displayed author:\s*([\w-]+)',t['judge_output'])
    s=int(r['score']) if r['score'].isdigit() else r['score']
    if len(fs)!=1 or str(fs[0])!=str(r['score']): mism+=1; issues.append(('score',r['rating_id'],r['response_id'],r['session'],r['score'],fs))
    if t['response_id']!=r['response_id'] or t['session']!=int(r['session']) or t['displayed_label']!=r['displayed_label']: issues.append(('meta',r['rating_id']))
    if da and da[0]!=r['displayed_label']: issues.append(('label-text',r['rating_id'],da,r['displayed_label']))
    if t['judge_model']!='atlas-7': issues.append(('judge',r['rating_id'],t['judge_model']))
print('score mismatches',mism)
for i in issues: print(i)
